{
  "returncode": 0,
  "output_head": "   251	.question-item__body { font-weight: 600; font-size: 19px; margin-bottom: 10px; white-space: pre-line; }
   252	.question-item__options { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 6px; }
   253	.question-item__options li { background: var(--c-lavender); border-radius: 1000px; padding: 4px 12px; font-size: 15px; }
   254	.question-item__options li.is-correct { background: var(--c-success); color: var(--c-white); }
   255	.question-item__options li.is-correct::before { content: "✓ "; }
   256	.question-item__actions { display: flex; flex-direction: column; gap: 8px; align-items: flex-end; }
   257	.question-item__actions .buttons { justify-content: flex-end; }
   258	
   259	.option-rows { display: flex; flex-direction: column; gap: 10px; margin-bottom: 14px; }
   260	.option-row { display: grid; grid-template-columns: 1fr auto auto; gap: 12px; align-items: center; }
   261	
   262	.runs-table { width: 100%; border-collapse: collapse; }
   263	.runs-table th, .runs-table td { text-align: left; padding: 12px 8px; border-bottom: 1px solid var(--c-lavender); }
   264	.runs-table th { font-size: 14px; color: var(--c-muted); font-weight: 500; }
   265	.runs-table td:last-child { text-align: right; }
   266	
   267	.badge {
   268	  display: inline-block;
   269	  border-radius: 1000px;
   270	  padding: 3px 12px;
   271	  font-size: 14px;
   272	  font-weight: 600;
