import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["list", "row", "template"]

  add() {
    const index = this.rowTargets.length
    const num = index + 1
    const html = this.templateTarget.innerHTML
      .replaceAll("__INDEX__", String(index))
      .replaceAll("__NUM__", String(num))

    this.listTarget.insertAdjacentHTML("beforeend", html)
    const newRow = this.rowTargets[this.rowTargets.length - 1]
    const input = newRow?.querySelector("[data-role='body-input']")
    if (input) input.focus()
  }

  remove(event) {
    const row = event.currentTarget.closest("[data-option-rows-target='row']")
    if (!row) return

    row.remove()
    this.renumber()
  }

  toggleCheckbox(event) {
    const wrapper = event.currentTarget.closest(".checkbox")
    const checkbox = wrapper?.querySelector("input[type='checkbox']")
    if (checkbox) {
      checkbox.checked = !checkbox.checked
      checkbox.dispatchEvent(new Event("change", { bubbles: true }))
    }
  }

  renumber() {
    this.rowTargets.forEach((row, index) => {
      const num = index + 1
      const idInput = row.querySelector("[data-role='id']")
      const bodyLabel = row.querySelector("[data-role='body-label']")
      const bodyInput = row.querySelector("[data-role='body-input']")
      const correctHidden = row.querySelector("[data-role='correct-hidden']")
      const correctLabel = row.querySelector("[data-role='correct-label']")
      const correctInput = row.querySelector("[data-role='correct-input']")
      const removeButton = row.querySelector("[data-role='remove-button']")

      if (idInput) idInput.name = `question[option_rows][${index}][id]`

      if (bodyLabel) {
        bodyLabel.setAttribute("for", `question_option_${num}_body`)
        bodyLabel.textContent = `Option ${num}`
      }
      if (bodyInput) {
        bodyInput.id = `question_option_${num}_body`
        bodyInput.name = `question[option_rows][${index}][body]`
        bodyInput.placeholder = `Option ${num}`
        bodyInput.setAttribute("aria-label", `Option ${num}`)
      }

      if (correctHidden) correctHidden.name = `question[option_rows][${index}][correct]`
      if (correctLabel) {
        correctLabel.setAttribute("for", `question_option_${num}_correct`)
        correctLabel.textContent = `Option ${num} is correct`
      }
      if (correctInput) {
        correctInput.id = `question_option_${num}_correct`
        correctInput.name = `question[option_rows][${index}][correct]`
        correctInput.setAttribute("aria-label", `Option ${num} is correct`)
      }

      if (removeButton) {
        removeButton.setAttribute("aria-label", `Remove option ${num}`)
        removeButton.setAttribute("title", `Remove option ${num}`)
      }
    })
  }
}
EOF

cat <<'EOF' > app/javascript/controllers/question_active_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["item", "number", "summary"]

  connect() {
    this.queue = Promise.resolve()
  }

  toggle(event) {
    const checkbox = event.currentTarget
    const form = checkbox.closest("form")
    const item = checkbox.closest("[data-question-active-target='item']")
    const active = checkbox.checked

    if (item) {
      item.classList.toggle("question-item--inactive", !active)
    }
    this.updateNumbersAndSummary()

    const csrfToken = document.querySelector("meta[name='csrf-token']")?.content
    const url = form.action

    this.queue = this.queue
      .then(() =>
        fetch(url, {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "X-CSRF-Token": csrfToken || ""
          },
          credentials: "same-origin",
          keepalive: true,
          body: JSON.stringify({ question: { active } })
        }).then((response) => {
          if (!response.ok) throw new Error(`HTTP ${response.status}`)
        })
      )
      .catch(() => {
        checkbox.checked = !active
        if (item) {
          item.classList.toggle("question-item--inactive", active)
        }
        this.updateNumbersAndSummary()
      })
  }

  updateNumbersAndSummary() {
    let activeCount = 0
    const totalCount = this.itemTargets.length

    this.itemTargets.forEach((item, idx) => {
      const checkbox = item.querySelector("input[type='checkbox'][name='question[active]']")
      const isActive = checkbox ? checkbox.checked : false
      const numberEl = this.numberTargets[idx]
      if (isActive) {
        activeCount += 1
        if (numberEl) numberEl.textContent = String(activeCount)
      } else {
        if (numberEl) numberEl.textContent = "—"
      }
    })

    if (this.hasSummaryTarget) {
      const noun = totalCount === 1 ? "question" : "questions"
      this.summaryTarget.textContent = `${activeCount} of ${totalCount} ${noun} active`
    }
  }
}
EOF

cat <<'EOF' > app/javascript/controllers/preview_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["stage", "bannerAction"]
  static values = { questions: Array }

  connect() {
    if (this.questionsValue.length === 0) return
    this.restart()
  }

  restart() {
    this.index = 0
    this.score = 0
    this.answered = false
    this.renderQuestion()
  }

  renderBannerRestart(show) {
    if (!this.hasBannerActionTarget) return
    this.bannerActionTarget.replaceChildren()
    if (!show) return

    const button = document.createElement("button")
    button.type = "button"
    button.className = "btn btn--light btn--sm"
    button.textContent = "Start over"
    button.addEventListener("click", () => this.restart())
    this.bannerActionTarget.appendChild(button)
  }

  renderQuestion() {
    const total = this.questionsValue.length
    const question = this.questionsValue[this.index]

    this.renderBannerRestart(this.index > 0 || this.answered)
    this.stageTarget.replaceChildren()

    const numEl = document.createElement("div")
    numEl.className = "play-question__num"
    numEl.textContent = `Question ${this.index + 1} of ${total}`

    const bodyEl = document.createElement("div")
    bodyEl.className = "play-question__body"
    bodyEl.textContent = question.body

    const optionsEl = document.createElement("div")
    optionsEl.className = "play-options"

    const feedbackEl = document.createElement("div")
    feedbackEl.dataset.role = "feedback"

    const optionButtons = question.options.map((option) => {
      const btn = document.createElement("button")
      btn.type = "button"
      btn.className = "play-option"

      const letterEl = document.createElement("span")
      letterEl.className = "play-option__letter"
      letterEl.setAttribute("aria-hidden", "true")
      letterEl.textContent = option.letter

      const titleEl = document.createElement("span")
      titleEl.className = "play-option__title"
      titleEl.textContent = option.body

      const markEl = document.createElement("span")
      markEl.className = "play-option__mark"

      btn.append(letterEl, titleEl, markEl)
      optionsEl.appendChild(btn)

      return { option, btn, markEl }
    })

    optionButtons.forEach(({ option, btn }) => {
      btn.addEventListener("click", () => {
        this.pick(option, btn, optionButtons, optionsEl, feedbackEl)
      })
    })

    this.stageTarget.append(numEl, bodyEl, optionsEl, feedbackEl)
  }

  pick(pickedOption, pickedButton, optionButtons, optionsEl, feedbackEl) {
    if (this.answered) return
    this.answered = true

    if (pickedOption.correct) {
      this.score += 1
    }

    this.renderBannerRestart(true)

    optionsEl.classList.add("is-locked", "is-revealed")
    pickedButton.classList.add("is-picked")

    optionButtons.forEach(({ option, btn, markEl }) => {
      btn.disabled = true
      if (option.correct) {
        btn.classList.add("is-correct")
        btn.dataset.correct = "true"
        markEl.textContent = "✓ Correct"
      }
    })

    const statusEl = document.createElement("div")
    statusEl.className = `play-status ${pickedOption.correct ? "play-status--right" : "play-status--wrong"}`
    statusEl.setAttribute("role", "status")
    statusEl.textContent = pickedOption.correct ? "Correct!" : "Wrong!"

    const actionsEl = document.createElement("div")
    actionsEl.className = "preview-actions"

    const nextBtn = document.createElement("button")
    nextBtn.type = "button"
    nextBtn.className = "btn btn--pink"

    if (this.index + 1 < this.questionsValue.length) {
      nextBtn.textContent = "Next question"
      nextBtn.addEventListener("click", () => {
        this.index += 1
        this.answered = false
        this.renderQuestion()
      })
    } else {
      nextBtn.textContent = "See score"
      nextBtn.addEventListener("click", () => this.renderScore())
    }

    actionsEl.appendChild(nextBtn)
    feedbackEl.replaceChildren(statusEl, actionsEl)
  }

  renderScore() {
    this.renderBannerRestart(false)
    this.stageTarget.replaceChildren()

    const card = document.createElement("div")
    card.className = "result-card"

    const label = document.createElement("div")
    label.className = "result-card__label"
    label.textContent = "Quiz complete"

    const scoreEl = document.createElement("div")
    scoreEl.className = "result-card__score"
    scoreEl.textContent = `Score: ${this.score}/${this.questionsValue.length}`

    const actionsEl = document.createElement("div")
    actionsEl.className = "preview-actions"

    const restartBtn = document.createElement("button")
    restartBtn.type = "button"
    restartBtn.className = "btn btn--pink"
    restartBtn.textContent = "Start over"
    restartBtn.addEventListener("click", () => this.restart())

    actionsEl.appendChild(restartBtn)
    card.append(label, scoreEl, actionsEl)
    this.stageTarget.appendChild(card)
  }
}
EOF

